// server/tasks/logs/log-view.ts
import { open as open5, stat as stat3 } from "node:fs/promises";
var LOG_CHUNK = 64 * 1024;
var LOG_TAIL = 64 * 1024;
async function readLogChunk(file, offset) {
  let size = 0;
  try {
    size = (await stat3(file)).size;
  } catch {
    return { text: "", next: 0, size: 0 };
  }
  const start = Math.min(offset, size);
  const length = Math.min(size - start, LOG_CHUNK);
  const handle = await open5(file, "r");
  try {
    const buffer = Buffer.alloc(length);
    await handle.read(buffer, 0, length, start);
    let end = length;
    if (start + length < size) {
      while (end > 0 && (buffer[end - 1] & 192) === 128) end--;
      if (end > 0 && buffer[end - 1] >= 192) end--;
    }
    return {
      text: buffer.subarray(0, end).toString("utf8"),
      next: start + end,
      size
    };
  } finally {
    await handle.close();
  }
}
async function readLogTail(file, max = LOG_TAIL) {
  let size = 0;
  let at = 0;
  try {
    const info2 = await stat3(file);
    size = info2.size;
    at = info2.mtimeMs;
  } catch {
    return { text: "", size: 0, at: 0 };
  }
  const start = Math.max(0, size - max);
  const length = size - start;
  if (!length) return { text: "", size, at };
  const handle = await open5(file, "r");
  try {
    const buffer = Buffer.alloc(length);
    await handle.read(buffer, 0, length, start);
    let from = 0;
    if (start > 0)
      while (from < length && (buffer[from] & 192) === 128) from++;
    return { text: buffer.subarray(from).toString("utf8"), size, at };
  } finally {
    await handle.close();
  }
}

// server/tasks/workers/custom-tools.ts
function loadCustomTools(db, log = console.warn) {
  const rows = all(
    db,
    "SELECT name,source FROM worker_profiles WHERE layer='harness' ORDER BY name LIMIT 500"
  );
  for (const row3 of rows) {
    const problems = syncFromRules(
      row3.name,
      parseProfileSource(row3.source).rules
    );
    if (problems.length)
      log(
        `\u6267\u884C\u8005\u6863\u6848 harness/${row3.name} \u6CA1\u767B\u8BB0\u6210\u6267\u884C\u8005\uFF1A${problems.join("\uFF1B")}`
      );
  }
}

